function () use ($bot, $interaction, $build, $live, $audit) { if ($audit !== null) { [$action, $session, $target] = $audit; Log::info('discord bot: ' . $action, [ 'bot' => $bot->uuid, 'personal' => $session->personal, 'panel_user' => $session->actor()->id, 'discord_user' => $interaction->userId(), 'discord_name' => Ui::clip($interaction->username(), 64), 'guild' => $interaction->guildId(), 'target' => Ui::clip($target, 80), ]); } try { $message = $build(); } catch (Throwable $exception) { Log::error('discord bot: building a reply failed', [ 'custom_id' => $interaction->customId(), 'command' => $interaction->command(), 'error' => $exception->getMessage(), 'at' => $exception->getFile() . ':' . $exception->getLine(), ]); $message = Cards::error('Something went wrong on the panel while building that. The error has been logged for the administrator.'); } if (Ui::count($message['components'] ?? []) > Ui::MAX_COMPONENTS || Ui::textLength($message['components'] ?? []) > Ui::MAX_TEXT) { Log::warning('discord bot: a reply was over Discord\'s limits', [ 'components' => Ui::count($message['components'] ?? []), 'text' => Ui::textLength($message['components'] ?? []), ]); $message = Cards::error('That view came out larger than Discord allows. Try a narrower command.'); } $server = $message['_live'] ?? null; $files = $message['_files'] ?? []; $retry = (bool) ($message['_retry'] ?? false); unset($message['_files'], $message['_live'], $message['_retry']); $ok = $this->rest->editOriginal($bot, $interaction->token(), $message, is_array($files) ? $files : []); $channel = (string) $interaction->channelId(); if ($live !== null && is_string($server) && $server !== '') { if ($ok) { RefreshControlPanel::arm( $bot, $channel, $interaction->userId(), (bool) ($live['personal'] ?? false), (array) ($live['allowed'] ?? []), $interaction->token(), $server, $retry ? RefreshControlPanel::RETRY : RefreshControlPanel::INTERVAL, ); } } else { RefreshControlPanel::stop($bot, $channel, $interaction->userId()); } }; } private function refreshMember($member, Interaction $interaction): void { $avatar = is_string($interaction->user()['avatar'] ?? null) ? $interaction->user()['avatar'] : null; if ($member->username !== $interaction->username() || $member->avatar !== $avatar) { $member->forceFill(['username' => mb_substr($interaction->username(), 0, 191), 'avatar' => $avatar])->save(); } } private function account(Session $session, Interaction $interaction): array { $count = count(Servers::list($session->api)['servers']); if ($session->personal) { return Cards::account($session->actor(), $count, $session->bot->avatarUrl(), null, null, true); } return Cards::account( $session->actor(), $count, $session->member?->avatarUrl() ?? $interaction->avatarUrl(), $session->member?->username, $session->member?->created_at?->toAtomString(), false, ); } private function power(ClientApi $api, string $server, string $signal, array $allowed): array { if (!array_key_exists($signal, self::POWER)) { return Cards::error('That is not a power action.'); } if (!in_array($signal, $allowed, true)) { return Cards::error('**' . ucfirst($signal) . '** is switched off for this bot.'); } $found = Servers::find($api, $server); if ($found['server'] === null) { return Cards::error($found['error']); } $response = $api->post('servers/' . $found['server']['id'] . '/power', ['signal' => $signal]); if (!$response->ok()) { return ControlPanel::render($api, $found['server'], Format::escape($response->error())); } usleep(500_000); return ControlPanel::render($api, $found['server'], self::POWER[$signal]); } private function sendCommand(ClientApi $api, string $server, string $command): array { $command = ltrim(trim($command), '/'); if ($command === '') { return ControlPanel::build($api, $server, 'There was no command to send.'); } $found = Servers::find($api, $server); if ($found['server'] === null) { return Cards::error($found['error']); } $response = $api->post('servers/' . $found['server']['id'] . '/command', ['command' => $command]); if (!$response->ok()) { $message = in_array($response->status, [409, 502], true) ? 'The server has to be running to take a command.' : $response->error(); return ControlPanel::render($api, $found['server'], Format::escape($message)); } usleep(500_000); return ControlPanel::render($api, $found['server'], 'Sent ' . Format::code(Ui::clip($command, 120))); } private function commandModal(string $server): array { return Ui::modal("dzb:cmdm:{$server}", 'Send a console command', [ Ui::input('command', 'Command', false, true, 500, 'say Hello from Discord'), ]); } private function createBackup(ClientApi $api, string $server, string $name, string $ignored): array { $found = Servers::find($api, $server); if ($found['server'] === null) { return Cards::error($found['error']); } $server = $found['server']['id']; $body = array_filter([ 'name' => $name === '' ? null : mb_substr($name, 0, 191), 'ignored' => $ignored === '' ? null : mb_substr($ignored, 0, 2000), ], fn ($value) => $value !== null); $response = $api->post("servers/{$server}/backups", $body); if (!$response->ok()) { return Backups::list($api, $server, Format::escape($response->error())); } $made = (string) ($response->attributes()['name'] ?? $name); return Backups::list($api, $server, 'Started **' . Format::name($made !== '' ? $made : 'a backup') . '**. Press refresh in a moment to see it finish.'); } private function toggleLock(ClientApi $api, string $server, string $uuid): array { $server = $this->backupTarget($api, $server, $uuid); if (is_array($server)) { return $server; } $response = $api->post("servers/{$server}/backups/{$uuid}/lock"); if (!$response->ok()) { return Backups::detail($api, $server, $uuid, Format::escape($response->error())); } $locked = (bool) ($response->attributes()['is_locked'] ?? false); return Backups::detail($api, $server, $uuid, $locked ? 'Locked. It can no longer be deleted.' : 'Unlocked.'); } private function downloadLink(ClientApi $api, string $server, string $uuid): array { $server = $this->backupTarget($api, $server, $uuid); if (is_array($server)) { return $server; } $response = $api->get("servers/{$server}/backups/{$uuid}/download"); $url = (string) ($response->attributes()['url'] ?? ''); if (!$response->ok() || $url === '') { return Backups::detail($api, $server, $uuid, Format::escape($response->ok() ? 'The node did not hand back a link.' : $response->error())); } return Backups::detail($api, $server, $uuid, 'Your download is ready.', false, $url); } private function deleteBackup(ClientApi $api, string $server, string $uuid): array { $server = $this->backupTarget($api, $server, $uuid); if (is_array($server)) { return $server; } $response = $api->delete("servers/{$server}/backups/{$uuid}"); if (!$response->ok()) { return Backups::detail($api, $server, $uuid, Format::escape($response->error())); } return Backups::list($api, $server, 'The backup was deleted.'); } private function backupTarget(ClientApi $api, string $server, string $uuid): string|array { $found = Servers::find($api, $server); if ($found['server'] === null) { return Cards::error($found['error']); } if (preg_match('/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i', $uuid) !== 1) { return Backups::list($api, $found['server']['id'], 'That backup could not be found.'); } return $found['server']['id']; } private function alerts(Session $session, Interaction $interaction): array { $guild = $interaction->guildId(); if ($guild === null) { return Cards::error('Alerts post into a channel, so run this inside a Discord server.'); } return match ($interaction->subcommand()) { 'add' => $this->addAlert($session, $interaction, $guild), 'remove' => $this->removeAlert($session, $interaction, $interaction->string('alert')), default => Alerts::list($this->guildAlerts($session->bot, $guild)), }; } private function addAlert(Session $session, Interaction $interaction, string $guild): array { if (!$interaction->canManageGuild() && !$session->owner) { return Cards::error('Setting up alerts needs the **Manage Server** permission in this Discord.'); } $values = array_map( fn (?int $value) => $value === null ? null : max(1, min(100, $value)), ['cpu' => $interaction->integer('cpu'), 'memory' => $interaction->integer('memory'), 'disk' => $interaction->integer('disk')], ); $offline = (bool) ($interaction->option('offline') ?? false); if (array_filter($values) === [] && !$offline) { return Cards::error('Give it something to watch: a `cpu`, `memory` or `disk` percentage, or `offline:True`.'); } $found = Servers::find($session->api, $interaction->string('server')); if ($found['server'] === null) { return Cards::error($found['error']); } $server = Server::query()->where('uuid', $found['server']['uuid'])->first(); if ($server === null) { return Cards::error('That server could not be found.'); } $bot = $session->bot; $actor = $session->actor(); $channel = (string) ($interaction->option('channel') ?? $interaction->channelId() ?? ''); $role = $interaction->option('role'); if ($channel === '' || !ctype_digit($channel)) { return Cards::error('Pick a text channel for the alerts to go into.'); } if ($role === $guild && !$interaction->canMentionEveryone()) { return Cards::error('Pinging @everyone needs the **Mention @everyone** permission in this Discord. Pick a role instead.'); } $existing = DiscordBotAlert::query() ->where('bot_id', $bot->id) ->where('server_id', $server->id) ->where('channel_id', $channel) ->first(); if ($existing === null && DiscordBotAlert::query()->where('user_id', $actor->id)->where('bot_id', $bot->id)->count() >= self::MAX_ALERTS_PER_USER) { return Cards::error('There are already ' . self::MAX_ALERTS_PER_USER . ' alerts on this account. Remove one with `/alerts remove` first.'); } $alert = $existing ?? new DiscordBotAlert(); $alert->fill([ 'bot_id' => $bot->id, 'user_id' => $actor->id, 'server_id' => $server->id, 'guild_id' => $guild, 'channel_id' => $channel, 'role_id' => is_string($role) && ctype_digit($role) ? $role : null, 'cpu' => $values['cpu'], 'memory' => $values['memory'], 'disk' => $values['disk'], 'offline' => $offline, 'cooldown' => max(1, min(1440, $interaction->integer('cooldown') ?? 15)), ]); $alert->setRelation('server', $server); $posted = $this->rest->send($bot, $channel, Alerts::created($alert, $found['server'], $interaction->userId())); if (!$posted['ok']) { $hint = in_array($posted['status'] ?? null, [403, 404], true) ? "The bot cannot post in <#{$channel}>. Add it to this Discord with the button below, and make sure it can see and send messages in that channel." : 'Discord would not take the test message: ' . Format::escape($posted['message']); return Cards::error($hint, [Ui::link(BotConfig::inviteUrl($bot), 'Add the bot to this Discord')]); } $alert->forceFill(['state' => null, 'last_error' => null])->save(); return Alerts::list( $this->guildAlerts($bot, $guild), ($existing === null ? 'Now watching **' : 'Updated the alert for **') . Format::name($found['server']['name']) . "**. A confirmation was posted in <#{$channel}>.", ); } private function removeAlert(Session $session, Interaction $interaction, string $value): array { $guild = $interaction->guildId(); if ($guild === null || preg_match('/^alert-(\d+)$/', $value, $match) !== 1) { return Cards::error('Pick the alert from the list that appears as you type.'); } $alert = DiscordBotAlert::query()->with('server')->where('bot_id', $session->bot->id)->where('guild_id', $guild)->find((int) $match[1]); if ($alert === null) { return Alerts::list($this->guildAlerts($session->bot, $guild), 'That alert was already removed.'); } $mine = $session->personal ? $session->owner : $alert->user_id === $session->actor()->id; if (!$mine && !$interaction->canManageGuild()) { return Cards::error('Only the person who set that alert up, or somebody with **Manage Server**, can remove it.'); } $name = $alert->server?->name ?? 'that server'; $alert->delete(); return Alerts::list($this->guildAlerts($session->bot, $guild), 'Stopped watching **' . Format::name($name) . '**.'); } private function guildAlerts(DiscordBot $bot, string $guild) { return DiscordBotAlert::query()->with('server')->where('bot_id', $bot->id)->where('guild_id', $guild)->orderBy('id')->get(); } } 